export const questionsBank: Record<string, BankQuestion[]> = {
    english: [
        { id: 1, question: "Choose the word nearest in meaning: The boy was very INTELLIGENT", options: ["Dull", "Smart", "Lazy", "Rude"], answer: 1, topic: "Lexis & Structure", explanation: "Intelligent means having good reasoning ability, and 'smart' is its closest synonym here. 'Dull' is the opposite (antonym), while 'lazy' and 'rude' describe a person's attitude, not their mental ability." },
        { id: 2, question: "Choose the correct option: She ___ to school every day.", options: ["go", "goes", "going", "gone"], answer: 1, topic: "Lexis & Structure", explanation: "The subject 'She' is third person singular and the sentence describes a habit (every day), so the present simple verb takes an '-s': 'goes'. 'Go' is used with I/you/we/they, 'going' needs a form of 'be' (is going), and 'gone' is a past participle." },
        { id: 3, question: "What is the synonym for 'Benevolent'?", options: ["Wicked", "Kind", "Selfish", "Angry"], answer: 1, topic: "Lexis & Structure", explanation: "'Benevolent' means well-meaning, generous and caring about others, so 'kind' is the nearest meaning. Note the prefix 'bene-' like in 'benefit' and 'benefactor' — all point to something good." },
        { id: 4, question: "Choose the word opposite in meaning: The soldier was rewarded for his BRAVERY.", options: ["Courage", "Cowardice", "Boldness", "Valour"], answer: 1, topic: "Lexis & Structure", explanation: "The question asks for the opposite (antonym), not the meaning. Bravery is the quality of facing danger; its opposite is 'cowardice' — being easily frightened. Courage, boldness and valour all mean roughly the same as bravery, so they are synonyms." },
        { id: 5, question: "Neither the teacher nor the students ___ present when the bell rang.", options: ["is", "are", "was", "were"], answer: 3, topic: "Lexis & Structure", explanation: "With 'neither ... nor', the verb agrees with the subject nearest to it. The nearest subject is 'students' (plural), so we need a plural verb. The verb also agrees with the past tense 'rang', so 'were' is correct." },
        { id: 6, question: "The plural of 'criterion' is?", options: ["Criterions", "Criteria", "Criterias", "Criterion"], answer: 1, topic: "Lexis & Structure", explanation: "'Criterion' comes from Greek, and Greek words ending in '-on' form their plural by changing '-on' to '-a': criterion → criteria. Similar examples are phenomenon → phenomena and datum → data. 'Criterias' is wrong because an English '-s' is not added to this word." },
        { id: 7, question: "Identify the odd word out: mango, orange, carrot, guava.", options: ["Mango", "Orange", "Carrot", "Guava"], answer: 2, topic: "Oral English", explanation: "Three of the words are fruits (mango, orange, guava) while 'carrot' is a vegetable (a root crop). The odd one out is therefore 'carrot'." },
        { id: 8, question: "Choose the correct spelling:", options: ["Occassion", "Ocassion", "Occasion", "Ocasion"], answer: 2, topic: "Oral English", explanation: "The correct spelling is 'occasion' — double 'c', single 's'. A useful memory aid: the word contains 'cc' and only one 's'." },
        { id: 9, question: "In the word 'Chemistry', which sound does the letters 'ch' represent?", options: ["/tʃ/ as in chair", "/k/ as in kite", "/ʃ/ as in shoe", "/dʒ/ as in jazz"], answer: 1, topic: "Oral English", explanation: "At the beginning of words of Greek origin such as chemistry, chemist, chaos and chorus, 'ch' is pronounced /k/. In everyday English words like chair or church, 'ch' is /tʃ/." },
        { id: 10, question: "Which of these words has the stress on the SECOND syllable?", options: ["Table", "Beauty", "Begin", "Water"], answer: 2, topic: "Oral English", explanation: "Say the word aloud: be-GIN. 'Table', 'beauty' and 'water' are stressed on the first syllable (TA-ble, BEAU-ty, WA-ter), while 'begin' is stressed on the second (be-GIN)." },
    ],
    math: [
        { id: 1, question: "Simplify: 2x + 3x - x", options: ["4x", "5x", "3x", "2x"], answer: 0, topic: "Algebra", explanation: "Collect like terms: 2x + 3x = 5x, and 5x - x = 4x. So the answer is 4x." },
        { id: 2, question: "Find x if 2x = 10", options: ["2", "5", "10", "20"], answer: 1, topic: "Algebra", explanation: "Divide both sides of the equation by 2: 2x/2 = 10/2, giving x = 5." },
        { id: 3, question: "What is the probability of getting a head when tossing a coin?", options: ["1", "1/2", "1/3", "0"], answer: 1, topic: "Probability", explanation: "Probability = (number of favourable outcomes) / (total number of possible outcomes). A fair coin has 2 equally likely outcomes (head or tail) and only 1 of them is a head, so P(head) = 1/2." },
        { id: 4, question: "If a = 3 and b = 4, find the value of a² + b².", options: ["7", "12", "25", "49"], answer: 2, topic: "Algebra", explanation: "Substitute the values: a² + b² = 3² + 4² = 9 + 16 = 25. This is the same as 5², the classic 3-4-5 right triangle relationship." },
        { id: 5, question: "Solve for x: 3x + 5 = 20", options: ["3", "5", "7", "15"], answer: 1, topic: "Algebra", explanation: "Subtract 5 from both sides: 3x = 20 - 5 = 15. Then divide both sides by 3: x = 15/3 = 5." },
        { id: 6, question: "What is the value of sin 30°?", options: ["1/2", "√3/2", "1", "0"], answer: 0, topic: "Trigonometry", explanation: "Sin 30° = 1/2. This comes from the 30-60-90 triangle (opposite side : hypotenuse = 1 : 2). Remember: sin 30° = 1/2, sin 45° = √2/2, sin 60° = √3/2, sin 90° = 1." },
        { id: 7, question: "In a right-angled triangle, the side opposite the right angle is called the?", options: ["Adjacent", "Opposite", "Hypotenuse", "Tangent"], answer: 2, topic: "Trigonometry", explanation: "The hypotenuse is the longest side of a right-angled triangle and it is always opposite the 90° angle. The adjacent and opposite sides are defined relative to the angle being considered." },
        { id: 8, question: "Differentiate y = x³ with respect to x.", options: ["3x²", "x²", "3x", "x⁴/4"], answer: 0, topic: "Calculus", explanation: "Use the power rule: if y = xⁿ then dy/dx = n·xⁿ⁻¹. So for y = x³, dy/dx = 3x³⁻¹ = 3x²." },
        { id: 9, question: "∫ 2x dx = ?", options: ["x² + C", "2x² + C", "x + C", "x³ + C"], answer: 0, topic: "Calculus", explanation: "In integration the power rule is reversed: ∫ xⁿ dx = xⁿ⁺¹/(n+1) + C. So ∫2x dx = 2·x²/2 + C = x² + C. The constant C is added because the integral of a constant is zero yet the antiderivative is not unique." },
        { id: 10, question: "A bag contains 3 red and 5 blue balls. What is the probability of picking a red ball?", options: ["3/5", "3/8", "5/8", "1/3"], answer: 1, topic: "Probability", explanation: "Total balls = 3 + 5 = 8. Favourable outcomes (red) = 3. So P(red) = 3/8. There are 8 possible balls to pick, not 5." },
    ],
    biology: [
        { id: 1, question: "The powerhouse of the cell is?", options: ["Nucleus", "Mitochondrion", "Ribosome", "Chloroplast"], answer: 1, topic: "Cell Biology", explanation: "The mitochondrion is called the powerhouse of the cell because aerobic respiration happens there, releasing the energy (ATP) the cell needs. The nucleus controls the cell, ribosomes make proteins, and chloroplasts carry out photosynthesis in plant cells." },
        { id: 2, question: "Which blood group is universal donor?", options: ["A", "B", "AB", "O"], answer: 3, topic: "Human Anatomy", explanation: "Group O has no A or B antigens on its red cells, so it can be given to people of any ABO group — hence 'universal donor'. Group AB is the universal recipient because it has no anti-A or anti-B antibodies." },
        { id: 3, question: "The basic unit of life is the?", options: ["Tissue", "Cell", "Organ", "Molecule"], answer: 1, topic: "Cell Biology", explanation: "The cell is the smallest structural and functional unit of a living organism. Cells group together to form tissues, tissues form organs, and organs form systems." },
        { id: 4, question: "Which organelle is responsible for protein synthesis?", options: ["Lysosome", "Ribosome", "Vacuole", "Golgi body"], answer: 1, topic: "Cell Biology", explanation: "Ribosomes translate mRNA into proteins (polypeptides). Lysosomes digest waste, the Golgi body modifies and packages proteins after they are made, and vacuoles store materials and water." },
        { id: 5, question: "A person with the genotype AS is said to be?", options: ["Normal", "A carrier of sickle cell", "Sickler", "Colour blind"], answer: 1, topic: "Genetics", explanation: "AS means one normal haemoglobin gene (A) and one sickle gene (S). The person does not normally show sickle cell anaemia but can pass the S gene to their children — they are a carrier (trait). AA is normal and SS is a sickler." },
        { id: 6, question: "In genetics, the physical appearance of an organism is its?", options: ["Genotype", "Phenotype", "Allele", "Chromosome"], answer: 1, topic: "Genetics", explanation: "The phenotype is the observable characteristic (eye colour, height, blood group). The genotype is the genetic make-up (the actual alleles, e.g. Tt) that produces the phenotype." },
        { id: 7, question: "Organisms that break down dead matter are called?", options: ["Producers", "Consumers", "Decomposers", "Herbivores"], answer: 2, topic: "Ecology", explanation: "Decomposers — mainly bacteria and fungi — break down dead plants and animals, releasing nutrients back into the soil. They are essential for nutrient cycling. Producers make their own food and consumers feed on others." },
        { id: 8, question: "Which of the following is a biotic factor in an ecosystem?", options: ["Temperature", "Rainfall", "Predation", "Soil pH"], answer: 2, topic: "Ecology", explanation: "Biotic factors are the living parts of an ecosystem — predators, prey, competitors, parasites and disease. Temperature, rainfall and soil pH are abiotic (non-living) factors." },
        { id: 9, question: "Water is absorbed from the soil mainly by?", options: ["Leaves", "Root hairs", "Stem", "Flowers"], answer: 1, topic: "Human Anatomy", explanation: "Root hairs are tiny extensions of root epidermal cells. Their huge total surface area allows rapid absorption of water and dissolved mineral salts by osmosis. Leaves mainly lose water through transpiration." },
        { id: 10, question: "The exchange of gases in the lungs takes place in the?", options: ["Bronchi", "Trachea", "Alveoli", "Larynx"], answer: 2, topic: "Human Anatomy", explanation: "Alveoli are tiny air sacs at the end of the bronchioles. Their thin walls, moist surface and rich blood supply let oxygen diffuse into the blood and carbon dioxide diffuse out. The trachea and bronchi are only air passages." },
    ],
    chemistry: [
        { id: 1, question: "What is the atomic number of Carbon?", options: ["6", "8", "12", "14"], answer: 0, topic: "Atomic Structure", explanation: "The atomic number is the number of protons in the nucleus — carbon has 6 protons, so its atomic number is 6. The mass number is 12 (6 protons + 6 neutrons), which is why options 12 and 14 are common traps." },
        { id: 2, question: "pH of neutral solution is?", options: ["0", "7", "14", "1"], answer: 1, topic: "Acids & Bases", explanation: "A pH of 7 is neutral (pure water at 25 °C). Values below 7 are acidic and values above 7 are basic/alkaline. The pH scale runs from 0 to 14." },
        { id: 3, question: "Which of these is the chemical symbol for Sodium?", options: ["S", "So", "Na", "N"], answer: 2, topic: "Atomic Structure", explanation: "Sodium's symbol is Na, from its Latin name 'natrium'. Likewise K for potassium (kalium) and Fe for iron (ferrum). 'S' is sulphur and 'N' is nitrogen." },
        { id: 4, question: "How many electrons are in the third shell of a chlorine atom (atomic number 17)?", options: ["2", "7", "8", "17"], answer: 1, topic: "Atomic Structure", explanation: "Electrons fill shells 2, 8, 8 for the first 20 elements. Chlorine (17) has 2 in the first shell, 8 in the second, leaving 17 - 10 = 7 in the third shell — which is why chlorine is in Group VII." },
        { id: 5, question: "Which of the following is an organic compound?", options: ["NaCl", "Methane (CH₄)", "H₂SO₄", "CaCO₃"], answer: 1, topic: "Organic Chemistry", explanation: "Organic compounds contain carbon atoms bonded to hydrogen (C–H bonds). Methane, CH₄, is the simplest organic compound. NaCl, H₂SO₄ and CaCO₃ are inorganic, although CaCO₃ contains carbon." },
        { id: 6, question: "The general formula for alkanes is?", options: ["CnH2n", "CnH2n+2", "CnH2n-2", "CnHn"], answer: 1, topic: "Organic Chemistry", explanation: "Alkanes are saturated hydrocarbons with only single C–C bonds, so they contain the maximum number of hydrogen atoms: CnH2n+2. Alkenes (one double bond) are CnH2n and alkynes (a triple bond) are CnH2n-2." },
        { id: 7, question: "Acid + Base → ?", options: ["Salt + Water", "Salt + Hydrogen", "Water only", "Salt only"], answer: 0, topic: "Acids & Bases", explanation: "Neutralisation is the reaction of an acid with a base to form a salt and water, e.g. HCl + NaOH → NaCl + H₂O. Salt + hydrogen is the reaction of an acid with a reactive metal." },
        { id: 8, question: "A solution with a pH of 3 is?", options: ["Strongly basic", "Weakly basic", "Acidic", "Neutral"], answer: 2, topic: "Acids & Bases", explanation: "pH 3 is below 7, so the solution is acidic. The lower the pH below 7, the more acidic the solution — pH 3 is a fairly strong acid but not as strong as pH 0 or 1." },
        { id: 9, question: "The number of moles in 4g of calcium (Ca = 40) is?", options: ["0.1", "0.5", "1", "4"], answer: 0, topic: "Mole Concept", explanation: "Moles = mass ÷ molar mass. Here 4 g ÷ 40 g/mol = 0.1 mole. Remember 1 mole of any substance contains 6.02 × 10²³ particles (Avogadro's number)." },
        { id: 10, question: "One mole of any gas at s.t.p. occupies?", options: ["22.4 dm³", "24 dm³", "1 dm³", "44 dm³"], answer: 0, topic: "Mole Concept", explanation: "At standard temperature and pressure (0 °C and 1 atm) one mole of any ideal gas occupies 22.4 dm³ (22,400 cm³). At room temperature and pressure the value is about 24 dm³ per mole." },
    ],
    physics: [
        { id: 1, question: "SI unit of force is?", options: ["Joule", "Newton", "Watt", "Pascal"], answer: 1, topic: "Mechanics", explanation: "Force is measured in newtons (N), where 1 N = 1 kg·m/s². A joule is a unit of energy/work, a watt is power, and a pascal is pressure." },
        { id: 2, question: "Speed of light in vacuum is?", options: ["3x10^8 m/s", "3x10^6 m/s", "3x10^5 m/s", "3x10^7 m/s"], answer: 0, topic: "Waves", explanation: "Light travels at approximately 3 × 10⁸ m/s in a vacuum (exactly 299,792,458 m/s). It travels slower in water or glass, but 3 × 10⁸ m/s is the standard value used in exams." },
        { id: 3, question: "A body at rest remains at rest unless acted upon by an external force. This is Newton's:", options: ["First law", "Second law", "Third law", "Law of gravitation"], answer: 0, topic: "Mechanics", explanation: "This is Newton's First Law — the law of inertia. The Second Law is F = ma, and the Third Law states that every action has an equal and opposite reaction." },
        { id: 4, question: "Work done is calculated as?", options: ["Mass × acceleration", "Force × distance", "Force ÷ time", "Power × time"], answer: 1, topic: "Mechanics", explanation: "Work = Force × distance moved in the direction of the force (W = Fd), measured in joules. Note that Power × time also gives energy, but the direct definition of work done by a force is F × d." },
        { id: 5, question: "The SI unit of electric current is?", options: ["Volt", "Ampere", "Ohm", "Coulomb"], answer: 1, topic: "Electricity", explanation: "Current is measured in amperes (A). A volt measures potential difference, an ohm measures resistance, and a coulomb measures electric charge." },
        { id: 6, question: "Ohm's law states that V = ?", options: ["IR", "I/R", "R/I", "I + R"], answer: 0, topic: "Electricity", explanation: "Ohm's law: Voltage (V) = Current (I) × Resistance (R). It applies to ohmic conductors at constant temperature, so V is directly proportional to I." },
        { id: 7, question: "Which type of wave is light?", options: ["Longitudinal", "Transverse", "Mechanical", "Sound wave"], answer: 1, topic: "Waves", explanation: "In light, the electric and magnetic fields oscillate perpendicular to the direction of travel, so light is a transverse wave. It is also electromagnetic, meaning it does not need a medium and can travel through a vacuum." },
        { id: 8, question: "The bending of light as it passes from air into water is called?", options: ["Reflection", "Refraction", "Diffraction", "Dispersion"], answer: 1, topic: "Waves", explanation: "Refraction is the change in direction of a wave when it enters a medium of different density, because its speed changes. Reflection is bouncing off a surface, diffraction is spreading around obstacles, and dispersion is the splitting of white light into colours." },
        { id: 9, question: "The particle of light is called a?", options: ["Electron", "Photon", "Neutron", "Proton"], answer: 1, topic: "Modern Physics", explanation: "Light behaves both as a wave and as a stream of particles called photons. A photon carries energy E = hf, where h is Planck's constant and f is the frequency. This is the basis of the photoelectric effect." },
        { id: 10, question: "Who proposed the theory of relativity?", options: ["Isaac Newton", "Albert Einstein", "Niels Bohr", "Max Planck"], answer: 1, topic: "Modern Physics", explanation: "Albert Einstein published the special theory of relativity in 1905 and the general theory in 1915. Newton gave the laws of motion and gravitation, Bohr worked on atomic models, and Planck introduced quantum theory." },
    ],
    agric: [
        { id: 1, question: "Which of these is a leguminous crop?", options: ["Maize", "Cowpea", "Cassava", "Rice"], answer: 1, topic: "Crop Production", explanation: "Cowpea is a legume (family Fabaceae). Its roots form nodules with nitrogen-fixing bacteria (Rhizobium), which convert atmospheric nitrogen into a form plants can use, improving soil fertility." },
        { id: 2, question: "The type of soil with the smallest particles is?", options: ["Sandy soil", "Clay soil", "Loamy soil", "Gravel"], answer: 1, topic: "Soil Science", explanation: "Clay particles are the smallest of all soil particles. Because clay has the largest surface area it holds water and nutrients best, but it drains poorly and is easily waterlogged. Sandy soil has the largest particles and drains fast." },
        { id: 3, question: "A crop planted to improve soil fertility is called?", options: ["Cereal", "Green manure", "Weed", "Pest"], answer: 1, topic: "Crop Production", explanation: "Green manure crops (often legumes such as cowpea or mucuna) are grown and then ploughed back into the soil while still green, adding organic matter and nitrogen to improve fertility." },
        { id: 4, question: "Maize is best planted at a spacing of about?", options: ["75 cm × 25 cm", "5 cm × 5 cm", "2 m × 2 m", "10 m × 10 m"], answer: 0, topic: "Crop Production", explanation: "Maize is commonly planted about 75 cm between rows and 25 cm within rows, giving roughly 53,000 plants per hectare. The spacing allows enough light, water and nutrients for each plant while maximising yield." },
        { id: 5, question: "Which of the following is a ruminant?", options: ["Pig", "Goat", "Rabbit", "Poultry"], answer: 1, topic: "Animal Husbandry", explanation: "Goats (like cattle and sheep) are ruminants — they have a four-chambered stomach (rumen, reticulum, omasum, abomasum) that allows them to digest grass with the help of micro-organisms. Pigs, rabbits and poultry are non-ruminants." },
        { id: 6, question: "The stomach chamber where food is stored and fermented by bacteria in ruminants is?", options: ["Rumen", "Abomasum", "Omasum", "Reticulum"], answer: 0, topic: "Animal Husbandry", explanation: "The rumen is the largest chamber. It acts as a fermentation vat where bacteria and protozoa break down cellulose from grass, and it stores food that the animal later brings back up to chew (rumination)." },
        { id: 7, question: "The R-factor in soil erosion refers to?", options: ["Rainfall erosivity", "Soil erodibility", "Slope", "Crop cover"], answer: 0, topic: "Farm Management", explanation: "In the Universal Soil Loss Equation (USLE), R is rainfall erosivity (how hard rain hits the soil), K is soil erodibility, LS is slope length/steepness and C is crop cover. High R means more aggressive rainfall and more erosion risk." },
        { id: 8, question: "Which is a method of soil conservation?", options: ["Bush burning", "Continuous grazing", "Terracing", "Deforestation"], answer: 2, topic: "Soil Science", explanation: "Terracing builds stepped levels on a slope, slowing runoff and preventing soil from being washed away. Bush burning, overgrazing and deforestation all expose soil and increase erosion." },
        { id: 9, question: "Crop rotation helps to?", options: ["Deplete nutrients", "Reduce pests and improve fertility", "Increase erosion", "Kill all soil organisms"], answer: 1, topic: "Farm Management", explanation: "Growing different crops in sequence prevents pests and diseases specific to one crop from building up, and alternating deep-rooted crops and legumes restores soil nutrients. Monocropping does the opposite." },
        { id: 10, question: "A disease of poultry that attacks the nervous system is?", options: ["Newcastle disease", "Mastitis", "Foot rot", "Rinderpest"], answer: 0, topic: "Animal Husbandry", explanation: "Newcastle disease is a viral disease of poultry causing twisting of the neck, paralysis and high mortality. Mastitis affects the udder, foot rot affects hooves of cattle, and rinderpest is a cattle disease." },
    ],
    govt: [
        { id: 1, question: "Nigeria became a republic in?", options: ["1960", "1963", "1979", "1999"], answer: 1, topic: "Constitution", explanation: "Nigeria gained independence on 1 October 1960 but remained under the British Queen as Head of State. On 1 October 1963 the country became a republic with a Nigerian President (Dr Nnamdi Azikiwe) as ceremonial Head of State." },
        { id: 2, question: "The first political party in Nigeria was?", options: ["NNDP", "NCNC", "AG", "NPC"], answer: 0, topic: "Political Parties", explanation: "The Nigerian National Democratic Party (NNDP), founded by Herbert Macaulay in 1923, was the first political party in Nigeria. NCNC came in 1944, the AG in 1951 and the NPC in 1951." },
        { id: 3, question: "The principle of separation of powers was propounded by?", options: ["John Locke", "Baron de Montesquieu", "Thomas Hobbes", "Jean Bodin"], answer: 1, topic: "Constitution", explanation: "Montesquieu explained separation of powers in 'The Spirit of the Laws' (1748), dividing government into the legislature (makes laws), executive (implements laws) and judiciary (interprets laws) to prevent tyranny." },
        { id: 4, question: "The organ of government that makes laws is the?", options: ["Executive", "Legislature", "Judiciary", "Press"], answer: 1, topic: "Constitution", explanation: "The legislature (National Assembly in Nigeria — Senate and House of Representatives) makes laws. The executive implements the laws, and the judiciary interprets them." },
        { id: 5, question: "Nigeria operates a system of government known as?", options: ["Pure presidential", "Federal presidential", "Unitary", "Confederal"], answer: 1, topic: "Constitution", explanation: "Nigeria is a federal republic with a presidential system: power is shared between the federal, state and local governments, and an executive President is both Head of State and Head of Government. It is not unitary because power is constitutionally divided." },
        { id: 6, question: "Universal adult suffrage means?", options: ["Only men can vote", "Only educated people vote", "All adult citizens have the right to vote", "Only property owners vote"], answer: 2, topic: "Elections", explanation: "Universal adult suffrage gives every adult citizen the right to vote regardless of sex, wealth, class or education. It is a key democratic principle and is expressed in Nigeria's constitution." },
        { id: 7, question: "The body that conducts federal elections in Nigeria is?", options: ["INEC", "NJC", "FEC", "NPC"], answer: 0, topic: "Elections", explanation: "INEC — the Independent National Electoral Commission — organises federal and state elections and registers voters, parties and candidates. The NJC advises on the judiciary and the FEC is the Federal Executive Council." },
        { id: 8, question: "A political party is best defined as?", options: ["A group of friends", "An organised group seeking political power", "A pressure group", "A trade union"], answer: 1, topic: "Political Parties", explanation: "A political party is an organised group of people with shared aims that seeks to win political power through elections and then form government. Pressure groups only try to influence government; they do not seek power themselves." },
        { id: 9, question: "The African Union (AU) was formerly known as?", options: ["ECOWAS", "OAU", "UN", "OPEC"], answer: 1, topic: "International Relations", explanation: "The Organisation of African Unity (OAU), founded in 1963, was transformed into the African Union (AU) in 2002. ECOWAS is a West African regional body and OPEC is an oil producers' organisation." },
        { id: 10, question: "A constitution that is contained in a single document is called?", options: ["Unwritten constitution", "Written constitution", "Conventions", "Statute of limitations"], answer: 1, topic: "Constitution", explanation: "A written constitution is set out in one formal, codified document (like Nigeria's 1999 Constitution). An unwritten constitution (like the UK's) is made up of conventions, statutes and court decisions rather than one document." },
    ],
    literature: [
        { id: 1, question: "A poem of fourteen lines is called a?", options: ["Sonnet", "Elegy", "Ode", "Ballad"], answer: 0, topic: "Poetry", explanation: "A sonnet is a fourteen-line poem with a fixed rhyme scheme, usually in iambic pentameter (Shakespeare's sonnets are a famous example). An elegy mourns the dead, an ode praises someone or something, and a ballad tells a story." },
        { id: 2, question: "'The moon is a silver coin' is an example of?", options: ["Simile", "Metaphor", "Personification", "Alliteration"], answer: 1, topic: "Poetry", explanation: "A metaphor directly states that one thing IS another without using 'like' or 'as'. A simile would say 'the moon is like a silver coin'. Personification gives human qualities to non-human things, and alliteration is the repetition of initial consonant sounds." },
        { id: 3, question: "The main character in a literary work is called the?", options: ["Antagonist", "Protagonist", "Narrator", "Chorus"], answer: 1, topic: "Drama", explanation: "The protagonist is the central character around whom the story revolves. The antagonist is the character or force that opposes them. The narrator is the voice telling the story — not necessarily the main character." },
        { id: 4, question: "A play that ends in the death of the hero is a?", options: ["Comedy", "Tragedy", "Farce", "Satire"], answer: 1, topic: "Drama", explanation: "A tragedy is a serious drama in which the hero suffers greatly and usually dies, often because of a tragic flaw (hamartia). A comedy ends happily, a farce is exaggerated humour, and satire mocks human foolishness." },
        { id: 5, question: "The major divisions of a play are called?", options: ["Chapters", "Acts", "Stanzas", "Verses"], answer: 1, topic: "Drama", explanation: "Plays are divided into acts (often 3 or 5) and scenes within each act. Chapters are used in prose novels and stanzas in poetry." },
        { id: 6, question: "'Things fall apart' was written by?", options: ["Wole Soyinka", "Chinua Achebe", "Ngũgĩ wa Thiong'o", "Ayi Kwei Armah"], answer: 1, topic: "African Prose", explanation: "Chinua Achebe published 'Things Fall Apart' in 1958; it tells the story of Okonkwo and the impact of colonialism on Igbo society. Soyinka is a playwright, Ngũgĩ wrote 'The River Between', and Armah wrote 'The Beautyful Ones Are Not Yet Born'." },
        { id: 7, question: "A narrative told from the 'I' point of view is?", options: ["Omniscient", "First person", "Third person", "Objective"], answer: 1, topic: "African Prose", explanation: "First-person narration uses 'I' and 'we' and is told by a character inside the story. An omniscient narrator knows everything, including characters' thoughts, and a third-person narrator uses 'he', 'she' and 'they'." },
        { id: 8, question: "'Pride and Prejudice' is a novel by?", options: ["Charles Dickens", "Jane Austen", "George Orwell", "Thomas Hardy"], answer: 1, topic: "Non-African Prose", explanation: "Jane Austen wrote 'Pride and Prejudice' (1813), which follows Elizabeth Bennet and Mr Darcy. Dickens wrote 'Great Expectations', Orwell wrote 'Animal Farm', and Hardy wrote 'Tess of the d'Urbervilles'." },
        { id: 9, question: "A figure of speech giving human qualities to non-human things is?", options: ["Metaphor", "Personification", "Hyperbole", "Irony"], answer: 1, topic: "Poetry", explanation: "Personification treats an object or idea as if it were human, e.g. 'the wind whispered'. Hyperbole is exaggeration, metaphor compares directly, and irony says the opposite of what is meant." },
        { id: 10, question: "An aside in drama is?", options: ["A speech to the audience not heard by other characters", "The prologue", "A stage direction", "A soliloquy"], answer: 0, topic: "Drama", explanation: "An aside is a short remark spoken to the audience, understood by them but assumed not to be heard by the other characters on stage. A soliloquy is a longer speech by a character alone on stage revealing inner thoughts." },
    ],
    crk: [
        { id: 1, question: "Who led the Israelites out of Egypt?", options: ["Abraham", "Moses", "Joshua", "David"], answer: 1, topic: "Old Testament", explanation: "God called Moses at the burning bush and used him to lead the Israelites out of slavery in Egypt through the Red Sea (Exodus 3–14). Joshua later led them into Canaan, Abraham was their ancestor, and David was a king." },
        { id: 2, question: "Jesus was born in?", options: ["Nazareth", "Jerusalem", "Bethlehem", "Jericho"], answer: 2, topic: "Life of Jesus", explanation: "Jesus was born in Bethlehem of Judea (Micah 5:2; Luke 2:4–7). He grew up in Nazareth, which is why he is called a Nazarene, and he was crucified in Jerusalem." },
        { id: 3, question: "The first book of the Bible is?", options: ["Exodus", "Genesis", "Matthew", "Psalms"], answer: 1, topic: "Old Testament", explanation: "Genesis is the first book of the Bible. Its name means 'beginning' and it covers creation, the flood and the stories of the patriarchs Abraham, Isaac, Jacob and Joseph." },
        { id: 4, question: "How many disciples did Jesus choose as apostles?", options: ["7", "10", "12", "70"], answer: 2, topic: "Life of Jesus", explanation: "Jesus chose twelve apostles (Mark 3:14–19). Seventy (or seventy-two) other disciples were also sent out, but the twelve are the ones called apostles." },
        { id: 5, question: "The Ten Commandments were given to Moses on Mount?", options: ["Sinai", "Olives", "Carmel", "Zion"], answer: 0, topic: "Old Testament", explanation: "Moses received the Ten Commandments from God on Mount Sinai (Exodus 20). The Mount of Olives and Mount Zion are in Jerusalem, and Mount Carmel is where Elijah confronted the prophets of Baal." },
        { id: 6, question: "Jesus' first miracle was performed at?", options: ["Cana", "Capernaum", "Bethany", "Jerusalem"], answer: 0, topic: "Life of Jesus", explanation: "At the wedding in Cana of Galilee, Jesus turned water into wine (John 2:1–11). John's gospel calls this the first of his signs." },
        { id: 7, question: "The longest book in the New Testament is?", options: ["Matthew", "Acts", "Romans", "Revelation"], answer: 2, topic: "New Testament", explanation: "Romans is the longest letter in the New Testament, written by Paul to the church in Rome. The book of Acts is historically longer in word count but Romans is the longest epistle; in exams Romans is the standard answer for the longest New Testament letter." },
        { id: 8, question: "Which apostle betrayed Jesus?", options: ["Peter", "Judas Iscariot", "Thomas", "John"], answer: 1, topic: "Life of Jesus", explanation: "Judas Iscariot betrayed Jesus for thirty pieces of silver (Matthew 26:14–16). Peter denied Jesus three times but did not betray him, Thomas doubted, and John was the beloved disciple." },
        { id: 9, question: "The fruit of the Spirit listed in Galatians includes?", options: ["Wealth", "Love", "Power", "Fame"], answer: 1, topic: "Themes", explanation: "Galatians 5:22–23 lists love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control. Wealth, power and fame are not part of the list — they are worldly values." },
        { id: 10, question: "Who was thrown into the lion's den?", options: ["Daniel", "Shadrach", "Elijah", "Jonah"], answer: 0, topic: "Old Testament", explanation: "Daniel was thrown into the lions' den for praying to God despite the king's decree, and God protected him (Daniel 6). Shadrach and his friends were thrown into a fiery furnace, and Jonah into the sea and then a great fish." },
    ],
    history: [
        { id: 1, question: "The trans-Saharan trade was mainly between West Africa and?", options: ["Europe", "North Africa", "Asia", "America"], answer: 1, topic: "Pre-Colonial", explanation: "Caravans crossed the Sahara between West African empires (Ghana, Mali, Songhai) and North African traders, exchanging gold, salt, kola nuts and slaves. This trade helped build the great West African empires." },
        { id: 2, question: "The British colonised Nigeria using which administrative system?", options: ["Direct rule", "Indirect rule", "Assimilation", "Apartheid"], answer: 1, topic: "Colonial Era", explanation: "Lord Frederick Lugard introduced indirect rule, governing through traditional rulers (Emirs, Obas, chiefs). It worked better in the north than in the south. 'Assimilation' was a French colonial policy." },
        { id: 3, question: "The amalgamation of Northern and Southern Nigeria took place in?", options: ["1900", "1914", "1922", "1946"], answer: 1, topic: "Colonial Era", explanation: "Lord Lugard amalgamated the Northern and Southern Protectorates in 1914 to form the Colony and Protectorate of Nigeria. This date is often called the birth of modern Nigeria." },
        { id: 4, question: "The first President of Nigeria was?", options: ["Nnamdi Azikiwe", "Tafawa Balewa", "Obafemi Awolowo", "Shehu Shagari"], answer: 0, topic: "Independence", explanation: "Dr Nnamdi Azikiwe became the first President when Nigeria became a republic in 1963. Tafawa Balewa was Prime Minister (Head of Government) from 1960, Awolowo was a regional leader, and Shagari became president in 1979." },
        { id: 5, question: "Nigeria gained independence on?", options: ["1 October 1960", "1 October 1963", "29 May 1999", "1 January 1900"], answer: 0, topic: "Independence", explanation: "Nigeria became independent on 1 October 1960 with Tafawa Balewa as Prime Minister. 1 October 1963 was when it became a republic, and 29 May 1999 marks the return to civilian rule under Obasanjo." },
        { id: 6, question: "The Scramble for Africa took place mainly in the?", options: ["16th century", "18th century", "Late 19th century", "21st century"], answer: 2, topic: "Colonial Era", explanation: "The Scramble for Africa was the rapid European colonisation of Africa between about 1881 and 1914, formalised at the Berlin Conference of 1884–85. Earlier centuries saw the slave trade, not the scramble." },
        { id: 7, question: "The Berlin Conference of 1884-85 was held to?", options: ["End the slave trade", "Partition Africa among European powers", "Create the UN", "Unite Africa"], answer: 1, topic: "World History", explanation: "The Berlin Conference, convened by Bismarck, set rules for European powers to claim and partition African territories without African representation. Its arbitrary borders are a root cause of many modern African conflicts." },
        { id: 8, question: "The Second World War ended in?", options: ["1918", "1939", "1945", "1960"], answer: 2, topic: "World History", explanation: "World War II ran from 1939 to 1945, ending in Europe in May 1945 and in Asia in September 1945 after the atomic bombings. World War I ended in 1918." },
        { id: 9, question: "The Oyo Empire was a powerful state of which ethnic group?", options: ["Igbo", "Yoruba", "Hausa", "Edo"], answer: 1, topic: "Pre-Colonial", explanation: "The Oyo Empire was a Yoruba state in south-western Nigeria, famous for its powerful cavalry (light horsemen) and its Alaafin rulers. The Igbo had decentralised societies, the Hausa had city-states, and the Edo built the Benin Kingdom." },
        { id: 10, question: "The Atlantic slave trade involved the transportation of Africans to?", options: ["Asia", "The Americas", "Europe only", "Australia"], answer: 1, topic: "Pre-Colonial", explanation: "The trans-Atlantic slave trade carried millions of enslaved Africans across the Atlantic to the Americas and the Caribbean, principally to work on plantations. It is often described as the 'triangular trade'." },
    ],
    economics: [
        { id: 1, question: "Scale of preference shows?", options: ["Wants arranged by importance", "Price list", "Income level", "Profit"], answer: 0, topic: "Micro Economics", explanation: "A scale of preference arranges a consumer's wants in order of importance, showing which want is satisfied first with limited income. It helps explain choice and opportunity cost." },
        { id: 2, question: "Demand curve slopes?", options: ["Upward", "Downward", "Vertical", "Horizontal"], answer: 1, topic: "Demand & Supply", explanation: "The demand curve slopes downward from left to right because of the law of demand: as price falls, quantity demanded rises (and vice versa). The supply curve slopes upward." },
        { id: 3, question: "The fundamental economic problem is?", options: ["Inflation", "Scarcity", "Unemployment", "Taxation"], answer: 1, topic: "Micro Economics", explanation: "Scarcity is the core economic problem — human wants are unlimited but resources (land, labour, capital, entrepreneurship) are limited. This forces choices and leads to opportunity cost." },
        { id: 4, question: "The 'opportunity cost' of a choice is?", options: ["The money paid", "The next best alternative forgone", "Total cost", "Profit made"], answer: 1, topic: "Micro Economics", explanation: "Opportunity cost is the value of the next best alternative you give up when making a choice. If you spend your last ₦1,000 on a book instead of shoes, the shoes are the opportunity cost." },
        { id: 5, question: "When supply exceeds demand, there is?", options: ["Shortage", "Surplus", "Equilibrium", "Inflation"], answer: 1, topic: "Demand & Supply", explanation: "If supply is greater than demand there is a surplus (excess supply), which usually forces prices down. When demand exceeds supply there is a shortage, which pushes prices up." },
        { id: 6, question: "The market structure with many sellers of identical products is?", options: ["Monopoly", "Oligopoly", "Perfect competition", "Monopsony"], answer: 2, topic: "Market Structure", explanation: "Perfect competition has many buyers and sellers, identical (homogeneous) products, free entry and exit, and sellers are price takers. Monopoly has one seller and oligopoly has a few large sellers." },
        { id: 7, question: "GDP stands for?", options: ["Gross Domestic Product", "General Domestic Price", "Gross Demand Product", "Government Domestic Policy"], answer: 0, topic: "Macro Economics", explanation: "Gross Domestic Product is the total market value of all final goods and services produced within a country in a given period. It measures the size of an economy." },
        { id: 8, question: "Inflation is best described as?", options: ["Fall in prices", "Persistent rise in the general price level", "Rise in output", "Fall in employment"], answer: 1, topic: "Macro Economics", explanation: "Inflation is a persistent increase in the general price level over time, which reduces the purchasing power of money. A fall in prices is deflation, not inflation." },
        { id: 9, question: "The central bank of Nigeria is?", options: ["First Bank", "CBN", "Ecobank", "NDIC"], answer: 1, topic: "Macro Economics", explanation: "The Central Bank of Nigeria (CBN) issues the naira, controls monetary policy and regulates commercial banks. First Bank and Ecobank are commercial banks, and the NDIC insures bank deposits." },
        { id: 10, question: "A normal good is one where demand rises when?", options: ["Income rises", "Price rises", "Income falls", "Substitutes increase"], answer: 0, topic: "Demand & Supply", explanation: "For a normal good, demand increases as consumers' income increases (positive income elasticity). For an inferior good, demand falls when income rises, e.g. cheaper substitutes." },
    ],
    commerce: [
        { id: 1, question: "The middleman between wholesaler and consumer is?", options: ["Producer", "Retailer", "Agent", "Broker"], answer: 1, topic: "Trade", explanation: "The retailer buys in small quantities from the wholesaler and sells directly to final consumers. The channel runs producer → wholesaler → retailer → consumer." },
        { id: 2, question: "Trade within a country's borders is called?", options: ["Foreign trade", "Home trade", "Entrepot trade", "Barter"], answer: 1, topic: "Trade", explanation: "Home (domestic) trade is buying and selling within one country's borders, split into wholesale and retail. Foreign trade is trade between countries, and entrepot trade is importing goods to re-export them." },
        { id: 3, question: "A document that lists goods, quantities and prices before a sale is a?", options: ["Invoice", "Quotation", "Receipt", "Cheque"], answer: 1, topic: "Trade", explanation: "A quotation is sent by a seller to a prospective buyer stating prices and terms before the order is placed. An invoice is issued after the goods are supplied, and a receipt proves payment has been made." },
        { id: 4, question: "A sole proprietorship has?", options: ["Unlimited liability", "Limited liability", "Many shareholders", "No owner"], answer: 0, topic: "Business Org", explanation: "A sole trader owns and runs the business alone and has unlimited liability, meaning personal assets can be used to settle business debts. Limited liability belongs to companies (Ltd/PLC)." },
        { id: 5, question: "A partner who neither contributes capital nor takes part in management but lends his name is?", options: ["Active partner", "Dormant partner", "Nominal partner", "Quasi partner"], answer: 2, topic: "Business Org", explanation: "A nominal (nominal/ostensible) partner lends only his name and reputation to the firm without contributing capital. A dormant partner contributes capital but does not take part in management." },
        { id: 6, question: "Which is not a function of money?", options: ["Medium of exchange", "Store of value", "Unit of account", "Production of goods"], answer: 3, topic: "Finance", explanation: "Money acts as a medium of exchange, a measure/unit of account, a store of value and a standard of deferred payment. Producing goods is a function of industry, not money." },
        { id: 7, question: "The 'marketing mix' consists of?", options: ["4 Ps: Product, Price, Place, Promotion", "3 Ps only", "5 Cs", "Cost and Profit"], answer: 0, topic: "Marketing", explanation: "The marketing mix is summarised as the 4 Ps — Product (what you sell), Price (what you charge), Place (where/how you sell it) and Promotion (how you tell customers)." },
        { id: 8, question: "A cheque is an order to a bank to?", options: ["Lend money", "Pay a stated sum to a named person", "Open an account", "Buy shares"], answer: 1, topic: "Finance", explanation: "A cheque is a written instruction from an account holder (drawer) authorising the bank to pay a stated amount to a named person or bearer from their account." },
        { id: 9, question: "Importing goods to re-export them is called?", options: ["Entrepot trade", "Home trade", "Barter", "Export trade"], answer: 0, topic: "Trade", explanation: "Entrepot trade means importing goods and re-exporting them, usually after storing or repackaging, without substantial processing. Countries with good ports (like Singapore) do this a lot." },
        { id: 10, question: "An insurance principle stating that the insured must tell the insurer all facts is?", options: ["Indemnity", "Utmost good faith", "Subrogation", "Insurable interest"], answer: 1, topic: "Business Org", explanation: "Utmost good faith (uberrimae fidei) requires the insured to disclose all material facts honestly. Indemnity means restoring the insured to their previous financial position, and insurable interest means you benefit from the thing insured." },
    ],
    accounting: [
        { id: 1, question: "Double entry rule: Debit the receiver and?", options: ["Credit the giver", "Debit the giver", "Credit the receiver", "None"], answer: 0, topic: "Double Entry", explanation: "The golden rule of double entry: debit the receiver and credit the giver. Every transaction affects two accounts, and total debits must always equal total credits." },
        { id: 2, question: "The account that shows the assets and liabilities of a business at a date is the?", options: ["Trading account", "Balance sheet", "Trial balance", "Cash book"], answer: 1, topic: "Final Accounts", explanation: "A balance sheet (statement of financial position) lists assets, liabilities and capital at a particular date. The trading account calculates gross profit, and a trial balance is a list of ledger balances used to check arithmetic." },
        { id: 3, question: "Gross profit is?", options: ["Sales - Cost of goods sold", "Sales - Expenses", "Revenue - Tax", "Capital - Drawings"], answer: 0, topic: "Double Entry", explanation: "Gross profit = Net sales − Cost of goods sold (opening stock + purchases − closing stock). Net profit is then gross profit minus operating expenses." },
        { id: 4, question: "Assets = ?", options: ["Liabilities - Capital", "Capital + Liabilities", "Capital - Liabilities", "Revenue + Expenses"], answer: 1, topic: "Double Entry", explanation: "The accounting equation: Assets = Capital + Liabilities. Everything a business owns must have been financed either by the owner (capital) or by outsiders (liabilities)." },
        { id: 5, question: "A trial balance that does not balance suggests?", options: ["Error", "Profit", "Capital", "Tax"], answer: 0, topic: "Trial Balance", explanation: "If total debits do not equal total credits, there is an error such as an arithmetic mistake, a single entry, or a wrong figure posted to one side. Note some errors (like compensating errors) do not affect the trial balance." },
        { id: 6, question: "Goods taken by the owner for personal use are recorded as?", options: ["Drawings", "Capital", "Purchases returns", "Sales"], answer: 0, topic: "Double Entry", explanation: "Goods taken by the owner reduce business stock and are treated as drawings — money taken out of the business. They are deducted from capital at year end and are not an expense." },
        { id: 7, question: "In a partnership, profits are shared according to?", options: ["Partnership deed", "Bank rules", "Government", "Number of staff"], answer: 0, topic: "Partnership", explanation: "The partnership deed (or agreement) states how profits and losses are shared, the capital contribution of each partner and interest on capital. If there is no deed, the Partnership Act gives equal shares." },
        { id: 8, question: "A business bought goods worth ₦5,000 on credit. The effect is?", options: ["Purchases increase, creditors increase", "Cash decreases, purchases decrease", "Capital increases", "Assets only"], answer: 0, topic: "Double Entry", explanation: "On credit purchase, the Purchases account is debited (purchases increase) and Creditors/Trade payables are credited (liabilities increase). No cash moves at the point of purchase." },
        { id: 9, question: "Which is a current asset?", options: ["Motor van", "Building", "Stock", "Machinery"], answer: 2, topic: "Final Accounts", explanation: "Stock (inventory) is a current asset because it is expected to be sold or used within a year. Motor vans, buildings and machinery are fixed (non-current) assets held for long-term use." },
        { id: 10, question: "A bank overdraft is a?", options: ["Current asset", "Current liability", "Fixed asset", "Capital"], answer: 1, topic: "Final Accounts", explanation: "An overdraft means the business owes money to its bank, repayable on demand, so it is a current liability. A positive bank balance would instead be a current asset." },
    ],
    business: [
        { id: 1, question: "Which of these is an office machine?", options: ["Typewriter", "Tractor", "Lathe", "Drilling machine"], answer: 0, topic: "Office Practice", explanation: "A typewriter is an office machine used for producing documents. Tractors and lathes are used in farming and manufacturing workshops, not in offices." },
        { id: 2, question: "Filing documents by subject matter is called?", options: ["Chronological filing", "Subject filing", "Numerical filing", "Geographical filing"], answer: 1, topic: "Office Practice", explanation: "Subject filing stores documents under topics or subject headings. Chronological filing uses dates, numerical filing uses numbers, and geographical filing uses places." },
        { id: 3, question: "A contract requires all of the following EXCEPT?", options: ["Offer", "Acceptance", "Consideration", "Friendship"], answer: 3, topic: "Business Law", explanation: "A valid contract needs offer, acceptance, consideration, intention to create legal relations and capacity. Friendship is not a legal requirement." },
        { id: 4, question: "A minor's contract is generally?", options: ["Voidable", "Fully binding", "Illegal", "Criminal"], answer: 0, topic: "Business Law", explanation: "Under contract law, a person under 18 has limited capacity, so most contracts with minors are voidable — the minor can cancel them. Contracts for necessities like food are exceptions." },
        { id: 5, question: "At the apex of a company's structure is the?", options: ["Board of directors", "Employees", "Customers", "Suppliers"], answer: 0, topic: "Management", explanation: "The board of directors is elected by shareholders and sets company policy and appoints the management team. Day-to-day operations are carried out by the managers and employees." },
        { id: 6, question: "The father of modern management (scientific management) is?", options: ["Frederick Taylor", "Adam Smith", "Peter Drucker", "Henri Fayol"], answer: 0, topic: "Management", explanation: "Frederick W. Taylor is known as the father of scientific management, using time studies to improve industrial efficiency. Fayol contributed administrative principles and Drucker modern management theory." },
        { id: 7, question: "An entrepreneur's main role is to?", options: ["Take risks and organise resources", "Only do accounting", "Only sell goods", "Only borrow money"], answer: 0, topic: "Entrepreneurship", explanation: "An entrepreneur combines land, labour and capital, takes the risk of the venture and makes decisions aimed at profit. They can perform many functions, but risk-bearing and organising are the core ones." },
        { id: 8, question: "Which of these is a business structure?", options: ["Sole proprietorship", "Government bank only", "Market only", "Church"], answer: 0, topic: "Entrepreneurship", explanation: "Sole proprietorship is a recognised business structure (along with partnership and limited company). A market is a place for trading, and a church is not a business structure." },
        { id: 9, question: "A limited liability company must have?", options: ["A memorandum and articles of association", "Only a bank account", "Only workers", "Only a logo"], answer: 0, topic: "Business Law", explanation: "To be registered as a limited company, the promoter files the memorandum of association (external rules) and the articles of association (internal rules) with the Corporate Affairs Commission." },
        { id: 10, question: "Which is a function of management?", options: ["Planning", "Trading", "Farming", "Accounting only"], answer: 0, topic: "Management", explanation: "The core management functions are planning, organising, staffing, directing (leading) and controlling. Trading, farming and accounting are business activities, not management functions." },
    ],
}

